INSERT /*HistoryMapper.insertHistory 사용자화면접근이력 INSERT */
INTO S_MG.TB_IMGSYL05
( 
	LOIN_IP_ADDR
	,USER_ID
	,CONCT_DTM
	,USER_NM
	,ORG_NM
	,MENU_ID
	,REGNT_ENO
	,REG_DTM
	,TRTR_ENO
	,TRT_DTM   
)
VALUES
( 
	#{loinIpAddr}
	,#{userId}
	,CURRENT_TIMESTAMP
	,#{userNm}
	,#{orgNm}
	,#{menuId}
	,#{regntEno}
	,CURRENT_TIMESTAMP
	,#{trtrEno}
	,CURRENT_TIMESTAMP
)
